import { createHash } from "node:crypto";
import { readdir, readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

export function scriptHashes(html) {
 const hashes = [];
 for (const [, attributes, body] of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)) {
  if (/\bsrc\s*=/i.test(attributes)) continue;
  // Hash the exact generated bytes, including whitespace, not the source template.
  hashes.push(`'sha256-${createHash("sha256").update(body).digest("base64")}'`);
 }
 return hashes;
}
export async function generatedPolicy(dist) {
 const hashes = new Set();
 for (const file of await readdir(dist, {recursive:true})) {
  if (!file.endsWith(".html")) continue;
  for (const hash of scriptHashes(await readFile(resolve(dist,file),"utf8"))) hashes.add(hash);
 }
 const scripts = ["'self'", ...[...hashes].sort()].join(" ");
 const template = await readFile(new URL("../public/_headers",import.meta.url),"utf8");
 const headers = template.replace(/script-src [^;\n]+/, `script-src ${scripts}`);
 // Cloudflare Pages has a 2,000-character per-line limit. Never deploy a truncated policy.
 if (headers.split("\n").some(line=>line.length>2000)) throw new Error("CSP exceeds Pages header line limit; split scripts into external assets");
 return headers;
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
 const dist = resolve(import.meta.dirname,"../dist");
 await writeFile(resolve(dist,"_headers"),await generatedPolicy(dist));
}
